const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');

const body = $('Webhook Login').item.json.body;
const cliente = $input.first().json;

if (!cliente || !cliente.password_hash) {
  return [{ json: { valido: false, motivo: 'no_existe' } }];
}

if (!cliente.verified) {
  return [{ json: { valido: false, motivo: 'email_no_verificado' } }];
}

const coincide = await bcrypt.compare(body.password, cliente.password_hash);

if (!coincide) {
  return [{ json: { valido: false, motivo: 'password_incorrecto' } }];
}

const SECRET = $env.KLEYSITES_JWT_SECRET;
const token = jwt.sign(
  { client_id: cliente.id, email: cliente.email },
  SECRET,
  { expiresIn: '7d' }
);

return [{ json: { valido: true, token, client_id: cliente.id } }];

const bcrypt = require('bcryptjs');

const body = $('Webhook Registro').item.json.body;

if (!body.email || !body.password || body.password.length < 8) {
  return [{ json: { error: true, motivo: 'email o password invalido (minimo 8 caracteres)' } }];
}

const hash = await bcrypt.hash(body.password, 10);

return [{ json: { error: false, email: body.email, password_hash: hash } }];

const jwt = require('jsonwebtoken');
const body = $json.body;
const auth = $json.headers.authorization || '';
const token = auth.replace('Bearer ', '');

if (!token) {
  return [{ json: { autorizado: false, motivo: 'sin_token' } }];
}

try {
  const SECRET = $env.KLEYSITES_JWT_SECRET;
  const payload = jwt.verify(token, SECRET);
  return [{
    json: {
      autorizado: true,
      client_id: payload.client_id,
      site_id: body.site_id,
      tipo: body.tipo,
      contenido: JSON.stringify(body.contenido || {}),
      orden: body.orden || 0,
      block_id: body.block_id || null,
      zona: body.zona || 'contenido',
      parent_id: body.parent_id || null,
      estilos: JSON.stringify(body.estilos || {})
    }
  }];
} catch (e) {
  return [{ json: { autorizado: false, motivo: 'token_invalido' } }];
}

