// Renderizador: registro de tipos + árbol (parent_id) + zonas + estilos
const filas = $input.all().map(i => i.json);

function parseJsonSafe(v) {
  if (v == null) return {};
  return typeof v === 'string' ? JSON.parse(v) : v;
}

const bloques = filas.map(b => ({
  ...b,
  contenido: parseJsonSafe(b.contenido),
  estilos: parseJsonSafe(b.estilos),
}));

// Traduce claves de `estilos` (jsonb libre) a CSS inline. Se amplía sin tocar el resto.
function estiloInline(estilos) {
  const mapa = {
    color: 'color', fondo: 'background', fuente: 'font-family',
    tamano: 'font-size', peso: 'font-weight', espaciado: 'padding',
    alineacion: 'text-align', radio: 'border-radius', ancho: 'width',
  };
  return Object.entries(estilos || {})
    .filter(([k]) => mapa[k])
    .map(([k, v]) => `${mapa[k]}:${v}`)
    .join(';');
}

// Un renderizador por tipo. Agregar un tipo nuevo = agregar una entrada acá,
// nunca hay que tocar el resto del archivo ni la tabla en Neon.
const renderers = {
  texto:      (c, s) => `<div style="${s}">${c.html || ''}</div>`,
  titulo:     (c, s) => { const n = c.nivel || 'h2'; return `<${n} style="${s}">${c.texto || ''}</${n}>`; },
  imagen:     (c, s) => `<img src="${c.src || ''}" alt="${c.alt || ''}" style="${s}">`,
  boton:      (c, s) => `<a href="${c.href || '#'}" style="${s}">${c.texto || 'Botón'}</a>`,
  icono:      (c, s) => `<span style="${s}">${c.nombre || ''}</span>`,
  separador:  (c, s) => `<hr style="${s}">`,
  espaciador: (c, s) => `<div style="height:${c.alto || '24px'};${s}"></div>`,
  video:      (c, s) => `<video src="${c.src || ''}" controls style="${s}"></video>`,
  seccion:    (c, s, hijos) => `<section style="${s}">${hijos}</section>`,
  columnas:   (c, s, hijos) => `<div style="display:flex;gap:16px;${s}">${hijos}</div>`,
};

function renderBloque(b, porPadre) {
  const s = estiloInline(b.estilos);
  const hijos = (porPadre[b.id] || [])
    .sort((a, z) => (a.orden || 0) - (z.orden || 0))
    .map(h => renderBloque(h, porPadre))
    .join('\n');
  const render = renderers[b.tipo];
  if (!render) return `<!-- tipo sin renderizador todavía: ${b.tipo} -->`;
  return render(b.contenido, s, hijos);
}

const porPadre = {};
bloques.forEach(b => {
  if (b.parent_id != null) {
    (porPadre[b.parent_id] = porPadre[b.parent_id] || []).push(b);
  }
});

const raices = bloques.filter(b => b.parent_id == null);
const porZona = { encabezado: [], contenido: [], pie: [] };
raices.forEach(b => (porZona[b.zona] || porZona.contenido).push(b));

function renderZona(lista) {
  return lista
    .sort((a, z) => (a.orden || 0) - (z.orden || 0))
    .map(b => renderBloque(b, porPadre))
    .join('\n');
}

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Mi sitio KleySites</title></head><body>
<header>${renderZona(porZona.encabezado)}</header>
<main>${renderZona(porZona.contenido)}</main>
<footer>${renderZona(porZona.pie)}</footer>
</body></html>`;

return [{ json: { html } }];

const jwt = require('jsonwebtoken');
const auth = $json.headers.authorization || '';
const token = auth.replace('Bearer ', '');
const nombre = ($json.body.nombre || '').trim();

if (!token) return [{ json: { autorizado: false } }];
if (!nombre) return [{ json: { autorizado: false, motivo: 'nombre_requerido' } }];

try {
  const payload = jwt.verify(token, $env.KLEYSITES_JWT_SECRET);

  // Convertir 'Tienda Luis' -> 'tienda-luis'
  const slug = nombre
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // quitar tildes
    .replace(/[^a-z0-9\s-]/g, '') // quitar caracteres raros
    .trim()
    .replace(/\s+/g, '-') // espacios -> guiones
    .replace(/-+/g, '-'); // colapsar guiones repetidos

  return [{ json: { autorizado: true, client_id: payload.client_id, nombre, slug } }];
} catch (e) {
  return [{ json: { autorizado: false } }];
}

// Genera 4 variantes candidatas a partir del slug original que el cliente pidio
const base = $('Validar token y generar slug').item.json.slug;
const random = Math.floor(100 + Math.random() * 900); // 3 digitos

const candidatos = [
  `${base}-pe`,
  `${base}-oficial`,
  `${base}-${random}`,
  `${base}-2`
];

return [{ json: { candidatos } }];

// Quita de la lista de candidatos los que ya salieron ocupados en la consulta
const candidatos = $('Generar sugerencias de slug').item.json.candidatos;
const ocupados = $input.all().map(i => i.json.slug);

const disponibles = candidatos.filter(c => !ocupados.includes(c));

return [{ json: { sugerencias: disponibles.slice(0, 3) } }];

const html = $json.html;
const slug = $('Buscar slug del sitio').item.json.slug;
const html_b64 = Buffer.from(html, 'utf-8').toString('base64');

return [{ json: { html_b64, slug } }];

const codigo = Math.floor(100000 + Math.random() * 900000).toString();
const expira = new Date(Date.now() + 15 * 60 * 1000).toISOString(); // 15 min
const anterior = $json;
return [{ json: { ...anterior, verification_code: codigo, verification_expires: expira } }];

const body = $('Webhook Confirmar código').item.json.body;
const cliente = $input.first().json;

if (!cliente || cliente.id === undefined) {
  return [{ json: { ok: false, motivo: 'no_existe' } }];
}

const expirado = new Date(cliente.verification_expires) < new Date();
if (expirado) {
  return [{ json: { ok: false, motivo: 'codigo_expirado' } }];
}

if (String(cliente.verification_code) !== String(body.codigo)) {
  return [{ json: { ok: false, motivo: 'codigo_incorrecto' } }];
}

return [{ json: { ok: true, client_id: cliente.id } }];

